Un sistema detecta si un mismo invitado escaneó su entrada dos veces. Necesita los dos índices de escaneo, en orden.

function primerEscaneoDuplicado(codigos) {
  for (let i = 0; i < codigos.length; i++) {
    for (let j = i + 1; j < codigos.length; j++) {
      if (codigos[i] === codigos[j]) {
        return [i, j];
      }
    }
  }
  return null;
}
